function zipStore(files){const enc=new TextEncoder(),local=[],central=[];let offset=0;const dt=dosDateTime();for(const file of files){const name=enc.encode(file.name),data=typeof file.data==='string'?enc.encode(file.data):file.data,crc=crc32(data),lh=concat([u32(0x04034b50),u16(20),u16(0x0800),u16(0),u16(dt.time),u16(dt.date),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),name,data]);local.push(lh);central.push(concat([u32(0x02014b50),u16(20),u16(20),u16(0x0800),u16(0),u16(dt.time),u16(dt.date),u32(crc),u32(data.length),u32(data.length),u16(name.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),name]));offset+=lh.length;}const cd=concat(central),body=concat(local),end=concat([u32(0x06054b50),u16(0),u16(0),u16(files.length),u16(files.length),u32(cd.length),u32(body.length),u16(0)]);return concat([body,cd,end]);}
function xlsxBlob(rows){const files=[{name:'[Content_Types].xml',data:'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>'},{name:'_rels/.rels',data:'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>'},{name:'xl/workbook.xml',data:'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="Sheet1" sheetId="1" r:id="rId1"/></sheets></workbook>'},{name:'xl/_rels/workbook.xml.rels',data:'<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>'},{name:'xl/worksheets/sheet1.xml',data:sheetXml([HEADERS,...rows])}];return new Blob([zipStore(files)],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'});}
async function exportProducts(keys){const unique=[...new Set(keys)].filter(k=>state.products.some(p=>productKey(p)===k));if(!unique.length)return toast('Selecione ao menos uma caneca.',true);const checked=unique.map(k=>{const p=state.products.find(x=>productKey(x)===k),v=exportValidation(p);return{k,p,...v};}),invalid=checked.filter(x=>x.errs.length),valid=checked.filter(x=>!x.errs.length);if(!valid.length)return toast('Nenhuma caneca selecionada está pronta para exportar.',true);if(invalid.length&&!confirm(`${invalid.length} caneca(s) com campos críticos serão ignoradas. Continuar com ${valid.length}?`))return;const rows=valid.map(x=>exportRow(x.p));if(rows.some(r=>r.length!==HEADERS.length))return toast('Mapeamento de planilha inválido.',true);const d=new Date(),filename=`canecafacil-lojaintegrada-${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}.xlsx`,url=URL.createObjectURL(xlsxBlob(rows)),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);const at=nowIso();await Promise.all(valid.map(x=>patchMug(x.k,{loja_integrada:{...liMeta(x.p),ultima_planilha_em:at,ultima_planilha_arquivo:filename,template:'loja-integrada-49-colunas-v2'}}).catch(()=>{})));await audit('lojaintegrada_planilha_gerada_v2',{arquivo:filename,quantidade:valid.length,ignoradas:invalid.length});state.selected.clear();toast(`Planilha gerada com ${valid.length} caneca(s).`);}

async function enhanceSettings(){if(!location.hash.includes('settings'))return;await loadGlobals();const root=$('#settings');if(!root||$('#cfGlobalSettings'))return;const wrap=document.createElement('section');wrap.id='cfGlobalSettings';wrap.className='panel';wrap.innerHTML=`<div class="panel-head"><div><h2>CanecaFácil · conteúdo comercial</h2><p>Perguntas padrão e cupons do site público.</p></div></div><div class="panel-body"><h3>Perguntas padrão</h3><div class="form"><label>Pergunta<input id="cfStdQ"></label><label>Resposta<input id="cfStdA"></label></div><div class="mini-actions" style="margin-top:8px"><button class="secondary" id="cfStdAdd">Criar pergunta</button></div><div id="cfStdList" style="margin-top:10px"></div><div class="form-section"><h3>Cupons</h3><div class="form"><label>Código<input id="cfCouponCode"></label><label>Tipo<select id="cfCouponType"><option value="percent">% desconto</option><option value="fixed">R$ desconto</option></select></label><label>Valor<input id="cfCouponValue" type="number" step="0.01"></label><label>Compra mínima<input id="cfCouponMin" type="number" step="0.01"></label><label>Validade<input id="cfCouponUntil" type="date"></label></div><div class="mini-actions" style="margin-top:8px"><button class="secondary" id="cfCouponAdd">Criar cupom</button></div><div id="cfCouponList" style="margin-top:10px"></div></div></div>`;root.appendChild(wrap);renderGlobals();$('#cfStdAdd').onclick=addStandardFaq;$('#cfCouponAdd').onclick=addCoupon;}
function renderGlobals(){if($('#cfStdList'))$('#cfStdList').innerHTML=Object.entries(state.faq||{}).map(([id,q])=>`<div class="notice" style="margin-bottom:6px"><b>${esc(q.pergunta||'')}</b><br>${esc(q.resposta||'')} <button class="secondary" data-del-std="${esc(id)}" style="float:right">Excluir</button></div>`).join('')||'<div class="notice">Nenhuma pergunta padrão.</div>';if($('#cfCouponList'))$('#cfCouponList').innerHTML=Object.entries(state.coupons||{}).map(([code,c])=>`<div class="notice" style="margin-bottom:6px"><b>${esc(code)}</b> · ${c.tipo==='fixed'?'R$':'%'} ${Number(c.valor||0)} · ${c.ativo===false?'inativo':'ativo'} <button class="secondary" data-toggle-coupon="${esc(code)}" style="float:right">${c.ativo===false?'Ativar':'Desativar'}</button></div>`).join('')||'<div class="notice">Nenhum cupom.</div>';$$('[data-del-std]').forEach(b=>b.onclick=()=>deleteStandard(b.dataset.delStd));$$('[data-toggle-coupon]').forEach(b=>b.onclick=()=>toggleCoupon(b.dataset.toggleCoupon));}
async function addStandardFaq(){const q=text($('#cfStdQ').value),a=text($('#cfStdA').value);if(!q||!a)return toast('Informe pergunta e resposta.',true);const id=safeKey(`${Date.now()}-${slug(q).slice(0,28)}`),obj={pergunta:q,resposta:a,ativo:true,criado_em:nowIso()};await fbWrite(`${FAQ_NODE}/${id}`,obj,'PUT');state.faq[id]=obj;$('#cfStdQ').value='';$('#cfStdA').value='';renderGlobals();toast('Pergunta criada.');}
async function deleteStandard(id){if(!confirm('Excluir esta pergunta padrão?'))return;await fetch(`${FIREBASE_BASE}/${FAQ_NODE}/${safeKey(id)}.json`,{method:'DELETE'});delete state.faq[id];renderGlobals();}
async function addCoupon(){const code=text($('#cfCouponCode').value).toUpperCase().replace(/[^A-Z0-9_-]/g,''),value=Number($('#cfCouponValue').value||0);if(!code||!(value>0))return toast('Informe código e valor.',true);const obj={tipo:$('#cfCouponType').value==='fixed'?'fixed':'percent',valor:value,valor_minimo:Number($('#cfCouponMin').value||0),validade:text($('#cfCouponUntil').value),ativo:true,criado_em:nowIso()};await fbWrite(`${COUPON_NODE}/${safeKey(code)}`,obj,'PUT');state.coupons[code]=obj;renderGlobals();toast('Cupom criado.');}
